{
  "items": [
    {
      "name": "Finset.le_sum_schlomilch",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u →\n        ∀ (n : ℕ),\n          ∑ k ∈ Finset.range (u n), f k ≤\n            ∑ k ∈ Finset.range (u 0), f k + ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u k)"
    },
    {
      "name": "Nat.sqrt_le_add",
      "module_name": "Mathlib.Data.Nat.Sqrt",
      "kind": "theorem",
      "type": "∀ (n : ℕ), n ≤ n.sqrt * n.sqrt + n.sqrt + n.sqrt"
    },
    {
      "name": "Real.sqrtTwoAddSeries_lt_two",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Trigonometric.Basic",
      "kind": "theorem",
      "type": "∀ (n : ℕ), Real.sqrtTwoAddSeries 0 n < 2"
    },
    {
      "name": "Nat.sqrt.iter_sq_le",
      "module_name": "Mathlib.Data.Nat.Sqrt",
      "kind": "theorem",
      "type": "∀ (n guess : ℕ), Nat.sqrt.iter n guess * Nat.sqrt.iter n guess ≤ n"
    },
    {
      "name": "ENNReal.le_tsum_schlomilch",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {u : ℕ → ℕ} {f : ℕ → ENNReal},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      StrictMono u → ∑' (k : ℕ), f k ≤ ∑ k ∈ Finset.range (u 0), f k + ∑' (k : ℕ), (↑(u (k + 1)) - ↑(u k)) * f (u k)"
    },
    {
      "name": "Real.sqrt_one_add_le",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, -1 ≤ x → √(1 + x) ≤ 1 + x / 2"
    }
  ]
}
